router = APIRouter(tags=["CRM marketing planning workspace"], include_in_schema=False)
_HEADERS = {"Cache-Control":"no-store","Content-Security-Policy":"default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'","Referrer-Policy":"no-referrer","X-Content-Type-Options":"nosniff"}
_PAGE = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>استراتژی و برنامه‌ریزی بازاریابی | فانل CRM</title><style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px 1fr}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:bold;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.toolbar{display:flex;justify-content:space-between;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:16px}.filters{display:flex;gap:9px;flex-wrap:wrap}.field{display:grid;gap:6px;font-size:11px;color:#778697}select,input{font:inherit;border:1px solid #dfe6ed;background:#fff;border-radius:9px;padding:10px;min-width:145px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0 0 12px}.status{min-height:20px;color:#718092;font-size:12px}.error{color:#a74137}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408;min-width:0}.label{color:#657487;font-size:11px}.value{font-size:22px;font-weight:bold;color:#1a334c;margin:9px 0 3px}.meta{font-size:10px;color:#8290a0;line-height:1.7}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:14px}.heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:0 0 12px}.heading h2{font-size:15px;margin:0}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:480px;font-size:11px}th,td{text-align:right;padding:9px 7px;border-bottom:1px solid #eef1f4}th{background:#f8fafc;color:#728092}td{color:#33465c}.list{display:grid;gap:8px}.item{border:1px solid #e8edf2;border-radius:9px;padding:11px;font-size:11px;line-height:1.8}.item strong{display:block;color:#304b60}.pill{display:inline-block;border-radius:99px;background:#eff4f7;color:#506879;padding:3px 8px;font-size:10px}.warn{background:#fff7e8;color:#8a641d}.good{background:#eaf6f1;color:#24745b}.bars{display:grid;gap:10px}.barrow{display:grid;grid-template-columns:110px 1fr 52px;gap:8px;align-items:center;font-size:11px}.track{height:9px;background:#edf2f6;border-radius:9px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#24b5a5,#17658e)}.links{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.link{border:1px solid #dfe7ee;background:#fff;color:#27536d;text-decoration:none;border-radius:8px;padding:9px 12px;font-size:11px}.empty,.foot{font-size:11px;line-height:1.8;color:#7b8998}.empty{text-align:center;padding:14px;border:1px dashed #d4dde6;border-radius:9px}.foot{margin-top:13px}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:8px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.main{padding:15px 12px}.toolbar{display:block}.filters{display:grid;grid-template-columns:1fr 1fr;margin-top:10px}.field,select,input{width:100%;min-width:0}.kpis{gap:7px}.card{padding:12px}.value{font-size:18px}}</style><script src="/assets/crm-marketing-planning.js" defer></script></head><body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM"><a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav" href="/workspace/crm-market-research">تحقیق و شناخت بازار</a><a class="nav active" href="/workspace/crm-marketing-planning" aria-current="page">استراتژی و برنامه‌ریزی بازاریابی</a><a class="nav" href="/workspace/crm-campaigns">کمپین و محتوا</a><a class="nav" href="/workspace/budget-scenario-comparison">سناریوهای بودجه</a></nav></aside><main class="main"><h1>استراتژی و برنامه‌ریزی بازاریابی</h1><p class="sub">هدف‌های دوره را با عملکرد ثبت‌شده، سناریوهای بودجه و تقویم اجرای کمپین کنار هم ببینید.</p><div class="toolbar"><div class="filters"><label class="field">فضای کاری<select id="workspace"><option value="">در حال دریافت…</option></select></label><label class="field">واحد سازمانی<select id="unit"><option value="">در حال دریافت…</option></select></label><label class="field">از تاریخ<input id="start" type="date"></label><label class="field">تا تاریخ<input id="end" type="date"></label></div><button id="refresh" type="button">به‌روزرسانی</button></div><p id="status" class="status" role="status" aria-live="polite"></p><section class="kpis"><article class="card"><div class="label">هدف‌های ارزیابی‌شده</div><div id="evaluated" class="value">—</div><div class="meta">شاخص‌هایی با هدف ثبت‌شده</div></article><article class="card"><div class="label">هدف‌های محقق‌شده</div><div id="met" class="value">—</div><div class="meta">طبق داده‌های مشاهده‌شده</div></article><article class="card"><div class="label">نیازمند توجه مدیر</div><div id="signals" class="value">—</div><div class="meta">فاصلهٔ هدف یا کمبود داده</div></article><article class="card"><div class="label">سناریوهای بودجه</div><div id="scenario-count" class="value">—</div><div class="meta">در واحد سازمانی انتخاب‌شده</div></article></section><div class="grid"><section class="card"><div class="heading"><h2>تحقق هدف‌های کمپین</h2><span class="meta">به تفکیک شاخص</span></div><div id="outcomes" class="bars"><div class="empty">در حال دریافت…</div></div><p class="foot">کمپین‌های بدون دادهٔ کافی جدا از هدف‌های کامل دیده می‌شوند؛ پوشش ثبت داده را پیش از تصمیم بررسی کنید.</p></section><section class="card"><div class="heading"><h2>هشدارهای برنامه</h2><span class="meta">توصیه برای بررسی انسانی</span></div><div id="signals-list" class="list"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>سناریوهای بودجه</h2><span class="meta">مبالغ بر اساس ارز</span></div><div id="scenarios" class="list"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>تقویم برنامه و اجرا</h2></div><div id="calendar" class="list"><div class="empty">در حال دریافت…</div></div></section></div><div class="links"><a class="link" href="/workspace/budget-scenario-comparison">مقایسهٔ سناریوهای بودجه</a><a class="link" href="/workspace/crm-campaigns">تقویم کمپین و محتوا</a><a class="link" href="/workspace/crm-analytics">داشبورد تحلیل بازاریابی</a></div><p class="foot">ارزیابی‌ها و هشدارها به دادهٔ ثبت‌شده متکی‌اند؛ این صفحه بودجه را خودکار تغییر نمی‌دهد و تصمیم نهایی با مدیر است.</p></main></div></body></html>"""
_SCRIPT = """(()=>{
const $=id=>document.getElementById(id),ws=$("workspace"),unit=$("unit"),fmt=new Intl.NumberFormat("fa-IR");
function say(s,e=false){$("status").textContent=s;$("status").classList.toggle("error",e)}function el(t,v,c=""){const n=document.createElement(t);n.textContent=String(v??"—");if(c)n.className=c;return n}
async function api(p){const r=await fetch(p,{credentials:"same-origin",headers:{Accept:"application/json","X-Workspace-ID":ws.value}});let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw Error(typeof d.detail==="string"?d.detail:"دریافت داده ناموفق بود");return d}
function bars(data){const box=$("outcomes");box.replaceChildren();const rows=Object.entries(data||{});if(!rows.length){box.append(el("div","برای این دوره هدف یا داده ثبت نشده است.","empty"));return}for(const [key,x] of rows){const row=document.createElement("div");row.className="barrow";row.append(el("span",key));const track=document.createElement("div");track.className="track";const fill=document.createElement("div");fill.className="fill";fill.style.width=(x.evaluated?100*x.met/x.evaluated:0)+"%";track.append(fill);row.append(track,el("span",fmt.format(x.met)+" از "+fmt.format(x.evaluated)));box.append(row)}}
function drawSignals(rows){const box=$("signals-list");box.replaceChildren();if(!rows?.length){box.append(el("div","هشداری برای بررسی گزارش نشده است.","empty"));return}for(const x of rows.slice(0,12)){const item=document.createElement("article");item.className="item";item.append(el("strong",x.metric_key+" · "+(x.signal_type==="measurement_gap"?"کمبود داده":"فاصله از هدف")));item.append(el("div",x.recommended_action));item.append(el("span",x.priority==="high"?"اولویت بالا":"اولویت متوسط","pill "+(x.priority==="high"?"warn":"")));box.append(item)}}
function money(map){return Object.entries(map||{}).map(([c,v])=>fmt.format(Number(v))+" "+c).join("، ")||"—"}
function drawScenarios(rows){const box=$("scenarios");box.replaceChildren();if(!rows?.length){box.append(el("div","سناریوی بودجه‌ای ثبت نشده است.","empty"));return}for(const x of rows){const item=document.createElement("article");item.className="item";item.append(el("strong",x.name));item.append(el("span",x.status==="draft"?"پیش‌نویس":"بایگانی‌شده","pill "+(x.status==="draft"?"good":"")));item.append(el("div",fmt.format(x.allocation_count)+" تخصیص"));box.append(item)}}
function drawCalendar(rows){const box=$("calendar");box.replaceChildren();if(!rows?.length){box.append(el("div","رویدادی در این دوره ثبت نشده است.","empty"));return}for(const x of rows.slice(0,12)){const item=document.createElement("article");item.className="item";item.append(el("strong",x.title));item.append(el("div",x.start_date+" تا "+x.end_date+" · "+(x.kind==="campaign"?"کمپین":"کار")+" · "+x.status));box.append(item)}}
async function load(){if(!ws.value||!unit.value)return;say("در حال محاسبهٔ هدف‌ها و خواندن برنامه…");const q=new URLSearchParams({period_start:$("start").value,period_end:$("end").value,organization_unit_id:unit.value,grouped_by:"channel"}),u=encodeURIComponent(unit.value);const results=await Promise.allSettled([api("/api/v1/crm/analytics/campaign-target-performance/portfolio?"+q),api("/api/v1/crm/budget-scenarios?organization_unit_id="+u+"&limit=100"),api("/api/v1/crm/marketing-calendar/events?"+new URLSearchParams({period_start:$("start").value,period_end:$("end").value,organization_unit_id:unit.value,limit:"100"}))]);
const [p,b,c]=results;if(p.status==="fulfilled"){const d=p.value,out=d.metric_outcomes||{},all=Object.values(out);$("evaluated").textContent=fmt.format(all.reduce((n,x)=>n+x.evaluated,0));$("met").textContent=fmt.format(all.reduce((n,x)=>n+x.met,0));$("signals").textContent=fmt.format(d.manager_signals.length);bars(out);drawSignals(d.manager_signals)}else{bars({});drawSignals([])}
if(b.status==="fulfilled"){$("scenario-count").textContent=fmt.format(b.value.length);drawScenarios(b.value)}else{$("scenario-count").textContent="—";drawScenarios([])}
if(c.status==="fulfilled")drawCalendar(c.value.events);else drawCalendar([]);
const errors=[p,b,c].filter(x=>x.status==="rejected").length;say(errors?"بخشی از گزارش در دسترس نیست؛ مجوز یا کامل‌بودن داده را بررسی کنید.":"گزارش برنامه‌ریزی برای دورهٔ انتخاب‌شده آماده است.",errors>0)}
async function init(){try{const w=await api("/api/v1/system/workspaces");ws.replaceChildren(...w.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!w.length)throw Error("فضای کاری یافت نشد");ws.value=w[0].id;const us=await api("/api/v1/system/organization-units");unit.replaceChildren(...us.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!us.length)throw Error("واحد سازمانی مجاز یافت نشد");unit.value=us[0].id;const now=new Date(),from=new Date(now);from.setDate(from.getDate()-29);$("start").value=from.toISOString().slice(0,10);$("end").value=now.toISOString().slice(0,10);await load()}catch(e){say("داده‌ها بارگیری نشد: "+e.message,true)}}
$("refresh").addEventListener("click",load);unit.addEventListener("change",load);ws.addEventListener("change",init);init();
})();"""
@router.get("/workspace/crm-marketing-planning", response_class=HTMLResponse)
async def marketing_planning_workspace() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-marketing-planning.js")
async def marketing_planning_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers=_HEADERS)
